package com.lenid.accountlab;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Phone-to-own-server commands only. No Bluetooth, CAN or OEM cloud commands. */
public final class ControlBridge {
 static final ExecutorService worker=Executors.newSingleThreadExecutor();static volatile boolean busy=false;
 static final Map<String,String[][]> menus=new HashMap<>();
 static{menus.put("Замок",new String[][]{{"Закрыть замки","doors.lock"},{"Открыть замки","doors.unlock"}});menus.put("Окна",new String[][]{{"Открыть окна","windows.open"},{"Закрыть окна","windows.close"},{"Приоткрыть окна","windows.vent"}});menus.put("Багажник",new String[][]{{"Открыть багажник","trunk.open"},{"Закрыть багажник","trunk.close"}});menus.put("Порт зарядки",new String[][]{{"Открыть порт зарядки","charge_port.open"},{"Закрыть порт зарядки","charge_port.close"}});menus.put("Найти авто",new String[][]{{"Мигнуть фарами","find.flash"},{"Фары и звуковой сигнал","find.flash_horn"}});menus.put("Найти автомобиль",menus.get("Найти авто"));}
 public static void attach(Activity a,View root){if(root instanceof TextView){String label=((TextView)root).getText().toString().trim();if(menus.containsKey(label)&&!java.util.Arrays.asList("Замок","Окна","Багажник","Порт зарядки").contains(label)){View target=root;while(!target.isClickable()&&target.getParent() instanceof View&&target!=a.findViewById(android.R.id.content))target=(View)target.getParent();if(target!=a.findViewById(android.R.id.content)){final String title=label;target.setEnabled(true);target.setOnClickListener(v->choose(a,title));root.setOnClickListener(v->choose(a,title));}}}if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++)attach(a,g.getChildAt(i));}}
 static void choose(Activity a,String label){String[][] choices=menus.get(label);String[] names=new String[choices.length];for(int i=0;i<names.length;i++)names[i]=choices[i][0];new AlertDialog.Builder(a).setTitle(label).setItems(names,(d,n)->selectVehicle(a,choices[n][0],choices[n][1])).setNegativeButton("Отмена",null).show();}
 interface Job{void run()throws Exception;}
 static void work(Activity a,Job job){if(busy){Toast.makeText(a,"Дождитесь ответа сервера",Toast.LENGTH_SHORT).show();return;}busy=true;worker.execute(()->{try{job.run();}catch(Exception e){a.runOnUiThread(()->error(a,e));}finally{busy=false;}});}
 static synchronized JSONObject api(Context a,String method,String path,JSONObject body)throws Exception{LabHttp http=new LabHttp(a);android.content.SharedPreferences p=a.getSharedPreferences("phone",0);String token=p.getString("access","");try{return http.call(method,path,body,token,null);}catch(LabHttp.Failure e){if(e.status!=401||token.isEmpty())throw e;JSONObject t=http.call("POST","/v1/auth/refresh",new JSONObject().put("refresh_token",p.getString("refresh","")),null,null);p.edit().putString("access",t.getString("access_token")).putString("refresh",t.getString("refresh_token")).commit();return http.call(method,path,body,t.getString("access_token"),null);}}
 static void error(Activity a,Exception e){if(a.isFinishing()||a.isDestroyed())return;String message="Нет связи с сервером. Результат отправки не подтверждён.";if(e instanceof LabHttp.Failure){String code=((LabHttp.Failure)e).code;if(code.equals("binding_revoked")||code.equals("binding_not_found"))message="Автомобиль больше не привязан к аккаунту.";else if(code.equals("rate_limited"))message="Слишком много команд. Подождите минуту.";else if(((LabHttp.Failure)e).status==401)message="Войдите в аккаунт заново.";else message="Сервер отклонил запрос: "+code;}new AlertDialog.Builder(a).setTitle("Команда не подтверждена").setMessage(message).setPositiveButton("Понятно",null).show();}
 static void selectVehicle(Activity a,String title,String action){work(a,()->{JSONObject me=api(a,"GET","/v1/me",null);JSONArray all=me.getJSONArray("vehicles");ArrayList<String> ids=new ArrayList<>(),labels=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject b=all.getJSONObject(i);if(b.optString("state").equals("active")){ids.add(b.getString("binding_id"));labels.add(b.optString("label","Автомобиль"));}}a.runOnUiThread(()->{if(a.isFinishing())return;if(ids.isEmpty()){new AlertDialog.Builder(a).setTitle("Автомобиль не привязан").setMessage("Сначала привяжите автомобиль по QR-коду.").setNegativeButton("Отмена",null).setPositiveButton("Мои автомобили",(d,w)->a.startActivity(new Intent(a,PhoneActivity.class).putExtra("section","vehicles"))).show();}else if(ids.size()==1)confirm(a,ids.get(0),title,action);else new AlertDialog.Builder(a).setTitle("Выберите автомобиль").setItems(labels.toArray(new String[0]),(d,n)->confirm(a,ids.get(n),title,action)).show();});});}
 static void confirm(Activity a,String id,String title,String action){String key=UUID.randomUUID().toString();new AlertDialog.Builder(a).setTitle(title+"?").setMessage("Команда будет отправлена на ваш сервер. Выполнение на автомобиле пока не подключено.").setNegativeButton("Отмена",null).setPositiveButton("Отправить",(d,w)->send(a,id,title,action,key)).show();}
 static void send(Activity a,String id,String title,String action,String key){work(a,()->{try{JSONObject r=api(a,"POST","/v1/bindings/"+id+"/commands",new JSONObject().put("action",action).put("idempotency_key",key));a.runOnUiThread(()->{if(a.isFinishing())return;new AlertDialog.Builder(a).setTitle(r.optString("state").equals("accepted")?"Команда принята сервером":"Статус команды").setMessage(title+"\n"+state(r.optString("state"))+"\n\nВыполнение на автомобиле отключено. Команда действительна 60 секунд.").setNegativeButton("Закрыть",null).setPositiveButton("История команд",(d,w)->history(a,id)).show();});}catch(Exception e){a.runOnUiThread(()->{if(a.isFinishing())return;if(e instanceof LabHttp.Failure){error(a,e);return;}new AlertDialog.Builder(a).setTitle("Ответ не получен").setMessage("Неизвестно, принял ли сервер команду. Повторная попытка проверит тот же запрос без создания дубликата.").setNegativeButton("Закрыть",null).setPositiveButton("Повторить",(d,w)->send(a,id,title,action,key)).show();});}});}
 static String state(String s){return s.equals("emulated")?"Выполнена на эмуляторе":s.equals("claimed")?"Получена эмулятором":s.equals("unconfirmed")?"Результат не подтверждён":s.equals("accepted")?"Принята, не выполнена":s.equals("expired")?"Срок истёк, не выполнена":s.equals("cancelled")?"Отменена":s;}
 public static void history(Activity a,String id){work(a,()->{JSONArray rows=api(a,"GET","/v1/bindings/"+id+"/commands",null).getJSONArray("commands");StringBuilder text=new StringBuilder();java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("HH:mm:ss",Locale.getDefault());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);text.append(fmt.format(new Date(row.getLong("created_at")*1000))).append(" · ").append(row.getString("title")).append("\n").append(state(row.getString("state"))).append("\n\n");}a.runOnUiThread(()->{if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("История команд").setMessage(text.length()==0?"Команд пока нет":text.toString()).setPositiveButton("Закрыть",null).show();});});}
}
